const express = require('express');
const router = express.Router();
const admin = require('firebase-admin');
const { db } = require('../db');

router.post('/api/notifications/topics/subscribe', requireAuth, async (req, res) => {
  const { registrationTokens, topicName } = req.body;

  if (!registrationTokens?.length || !topicName) {
    return res.status(400).json({ error: 'Tokens and topic required' });
  }

  const owned = await db.query(
    'SELECT token FROM user_push_devices WHERE user_id = $1 AND token = ANY($2)',
    [req.user.id, registrationTokens]
  );
  const verifiedTokens = owned.rows.map(r => r.token);
  if (verifiedTokens.length === 0) {
    return res.status(403).json({ error: 'Forbidden: no matching tokens owned by user' });
  }

  const response = await admin.messaging().subscribeToTopic(verifiedTokens, topicName);
  return res.json({ successCount: response.successCount, failureCount: response.failureCount });
});
